<script lang="ts">import UnavailableChart from './UnavailableChart.svelte'; import type { Role, Unavailable } from './types'; let { data }: { data: Role[] | Unavailable } = $props(); const max = $derived(Array.isArray(data) ? Math.max(1,...data.flatMap(d=>[d.count,d.target_max])) : 1);</script><figure class="chart"><h3>Role breakdown</h3>{#if !Array.isArray(data)}<UnavailableChart reason={data.reason}/>{:else}<p class="chart-legend">Solid: card count · outlined band: target range</p>{#each data as row}<div class="role-row"><div><span>{row.role}</span><span class="mono">{row.count} / target {row.target_min}–{row.target_max}</span></div><svg viewBox="0 0 320 18" role="img" aria-label={`${row.role}: ${row.count} cards, target ${row.target_min} to ${row.target_max}`}><rect x="1" y="5" width={row.count/max*316} height="8" class="data-bar"/><rect x={1+row.target_min/max*316} y="1" width={Math.max(1,(row.target_max-row.target_min)/max*316)} height="16" class="outline-bar"/></svg></div>{/each}{/if}</figure>